// Generated bytes and a current-process named pipe only. No audio-device APIs.
using System;
using System.Diagnostics;
using System.IO;
using System.IO.Pipes;
using System.Security.AccessControl;
using System.Security.Principal;
using System.Threading;
namespace SodaDesktopTests {
 public static class AudioChecks {
  static void Check(bool value,string message){if(!value)throw new InvalidOperationException(message);}
  static string Name(){return "SodaDesktopAudio-"+Guid.NewGuid().ToString("N");}
  sealed class Generated : SodaDesktopAudio.ISource {
   int count;public volatile bool Disposed;
   public bool Read(byte[] bytes,out long timestamp){timestamp=1234567;if(count++!=0)return false;for(int i=0;i<bytes.Length;i++)bytes[i]=(byte)(i%251);return true;}
   public void Dispose(){Disposed=true;}
  }
  sealed class Blocked : SodaDesktopAudio.ISource {
   readonly ManualResetEvent entered,unblock;public Blocked(ManualResetEvent entered,ManualResetEvent unblock){this.entered=entered;this.unblock=unblock;}
   public bool Read(byte[] pcm,out long timestamp){timestamp=0;entered.Set();unblock.WaitOne();return false;}public void Dispose(){}
  }
  static byte[] Read(Stream stream,int length){var bytes=new byte[length];int offset=0;while(offset<length){int count=stream.Read(bytes,offset,length-offset);if(count==0)throw new EndOfStreamException();offset+=count;}return bytes;}
  public static void Run(){
   var owner=WindowsIdentity.GetCurrent().User;var acl=SodaDesktopAudio.OwnerSecurity().GetAccessRules(true,true,typeof(SecurityIdentifier));Check(acl.Count==2,"Audio pipe must have explicit owner allow and network deny rules");
   var network=new SecurityIdentifier(WellKnownSidType.NetworkSid,null);bool ownerAllowed=false,networkDenied=false;
   foreach(PipeAccessRule rule in acl){Check(!rule.IsInherited&&rule.PipeAccessRights==PipeAccessRights.FullControl,"Audio pipe ACL rights");if(rule.IdentityReference.Equals(network)){Check(rule.AccessControlType==AccessControlType.Deny,"Audio pipe network deny");networkDenied=true;}else{Check(rule.IdentityReference.Equals(owner)&&rule.AccessControlType==AccessControlType.Allow,"Audio pipe ACL");ownerAllowed=true;}}
   Check(ownerAllowed&&networkDenied,"Audio pipe local-only ACL");
   int activated=0;var source=new Generated();string name=Name();
   using(var recorder=new SodaDesktopAudio(name,Process.GetCurrentProcess().Id,()=>true,()=>{Interlocked.Increment(ref activated);return source;})) {
    using(var client=new NamedPipeClientStream(".",name,PipeDirection.InOut,PipeOptions.Asynchronous)) {
     client.Connect(2000);var hello=Read(client,16);for(int i=0;i<hello.Length;i++)Check(hello[i]==SodaDesktopAudio.Hello[i],"PCM hello");
     var frame=Read(client,16+SodaDesktopAudio.PcmBytes);Check(BitConverter.ToInt32(frame,0)==3840&&BitConverter.ToUInt32(frame,4)==1&&BitConverter.ToInt64(frame,8)==1234567,"PCM frame header");for(int i=0;i<3840;i++)Check(frame[i+16]==(byte)(i%251),"Generated PCM bytes");
     Check(recorder.Stop(1000),"Audio stop after connection");
    }
   }
   Check(activated==1&&source.Disposed,"Generated source activation/disposal");
   activated=0;name=Name();
   using(var recorder=new SodaDesktopAudio(name,Process.GetCurrentProcess().Id+1,()=>true,()=>{Interlocked.Increment(ref activated);return new Generated();})) {
    using(var client=new NamedPipeClientStream(".",name,PipeDirection.InOut,PipeOptions.Asynchronous)){try{client.Connect(2000);Check(client.ReadByte()==-1,"Wrong process must receive no PCM/header");}catch(IOException){}}
    Check(recorder.Stop(1000),"Audio stop after denied PID");
   }
   Check(activated==0,"Audio source activated before PID verification");
   using(var recorder=new SodaDesktopAudio(Name(),Process.GetCurrentProcess().Id,()=>true,()=>new Generated())){var timer=Stopwatch.StartNew();Check(recorder.Stop(1000),"Cancel waiting audio pipe");Check(timer.ElapsedMilliseconds<1100,"Audio stop deadline");}
   bool permit=true;source=new Generated();name=Name();
   using(var recorder=new SodaDesktopAudio(name,Process.GetCurrentProcess().Id,()=>Volatile.Read(ref permit),()=>source)){
    using(var client=new NamedPipeClientStream(".",name,PipeDirection.InOut,PipeOptions.Asynchronous)){client.Connect(2000);Read(client,16);Volatile.Write(ref permit,false);Check(SpinWait.SpinUntil(()=>source.Disposed,1000),"Permission revoke must stop the source");Check(recorder.Stop(1000),"Audio revoke stop");}
   }
   var entered=new ManualResetEvent(false);var unblock=new ManualResetEvent(false);name=Name();
   using(var recorder=new SodaDesktopAudio(name,Process.GetCurrentProcess().Id,()=>true,()=>new Blocked(entered,unblock))){
    using(var client=new NamedPipeClientStream(".",name,PipeDirection.InOut,PipeOptions.Asynchronous)){
     client.Connect(2000);Read(client,16);Check(entered.WaitOne(1000),"Blocked source not entered");try{Check(!recorder.Stop(20),"Blocked source must report stop deadline");}finally{unblock.Set();}Check(recorder.Stop(1000),"Blocked source did not retire after release");
    }
   }
   entered.Dispose();unblock.Dispose();
   bool rejected=false;try{new SodaDesktopAudio("bad",1,()=>true,()=>new Generated());}catch(ArgumentException){rejected=true;}Check(rejected,"Unsafe audio pipe name accepted");
   Console.WriteLine("desktop_audio_checks_passed: owner ACL, matching/denied client PID before source activation, generated PCM framing, cancel/stop/dispose; no WASAPI activation/input/capture");
  }
 }
}
